d=ImageDraw.Draw(im)
# grid every 5 source px
for x in range(0,256,5):
 X=x*4; d.line((X,0,X,576),fill=(255,255,0),width=1)
 if x%10==0: d.text((X+2,2),str(x),fill=(255,255,0))
for y in range(0,144,5):
 Y=y*4; d.line((0,Y,1024,Y),fill=(255,255,0),width=1)
 if y%10==0: d.text((2,Y+2),str(y),fill=(255,255,0))
im.save('.tmp/grid.png')
PY"

